import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (no signature verification in this layer)
app.use((req, res, next) => {
  const auth = req.headers['authorization'];
  if (auth && auth.startsWith('Bearer ')) {
    try {
      const payload = JSON.parse(Buffer.from(auth.split('.')[1], 'base64').toString());
      req.tenantId = payload.tenant_id;
      req.userId = payload.sub;
    } catch (e) { /* continue without auth context */ }
  }
  next();
});

// Search documents with full-text search
app.get('/api/v1/documents/search', async (req, res) => {
  const { q, category, limit = 25, offset = 0 } = req.query;
  if (!q) return res.status(400).json({ error: 'query required' });

  // Build dynamic query with parameterized base but dynamic ORDER BY
  let query = `SELECT id, title, snippet(body, $1) as excerpt, category, created_at
    FROM documents
    WHERE tenant_id = $2
    AND tsv @@ plainto_tsquery('english', $1)`;
  const params = [q, req.tenantId];
  let paramIdx = 3;

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort parameter - vulnerable to SQL injection
  const sortCol = req.query.sort || 'created_at';
  const sortDir = req.query.dir || 'DESC';
  query += ` ORDER BY ${sortCol} ${sortDir}`;
  query += ` LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`;
  params.push(parseInt(limit), parseInt(offset));

  try {
    const result = await pool.query(query, params);
    res.json({ results: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Bulk export - uses COPY TO for performance
app.post('/api/v1/documents/export', async (req, res) => {
  const { format = 'csv', filter } = req.body;
  const client = await pool.connect();
  try {
    // filter.raw allows advanced users to pass custom WHERE clauses
    const whereClause = filter?.raw
      ? `WHERE tenant_id = '${req.tenantId}' AND (${filter.raw})`
      : `WHERE tenant_id = '${req.tenantId}'`;

    const copyQuery = `COPY (SELECT id, title, category, created_at FROM documents ${whereClause}) TO STDOUT WITH (FORMAT ${format === 'json' ? 'text' : 'csv'}, HEADER)`;
    const stream = client.query(require('pg-copy-streams').to(copyQuery));
    res.setHeader('Content-Type', format === 'json' ? 'application/json' : 'text/csv');
    stream.pipe(res);
    stream.on('end', () => client.release());
    stream.on('error', (err) => {
      console.error('Export error:', err.message);
      client.release();
      if (!res.headersSent) res.status(500).json({ error: 'export failed' });
    });
  } catch (err) {
    client.release();
    res.status(500).json({ error: 'export failed' });
  }
});

// Health check exposes version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION, node: process.version });
});

app.listen(3000, () => console.log('Document service listening on :3000'));
